// Intended function: bind prioritized shipments to available rail consists and deterministic node routes with bounded planning work.
#include "world/CargoRailSystem.hpp"
#include <algorithm>
#include <queue>
#include <unordered_set>
namespace elysium{void CargoRailSystem::upsertNode(RailNode n){nodes_[n.nodeId]=n;}void CargoRailSystem::upsertSegment(RailSegment s){segments_[s.segmentId]=s;}void CargoRailSystem::upsertConsist(RailConsist c){consists_[c.consistId]=c;}bool CargoRailSystem::submit(RailShipment s){if(!s.shipmentId||!s.quantity||!nodes_.contains(s.sourceNode)||!nodes_.contains(s.targetNode))return false;shipments_.push_back(s);return true;}std::optional<std::vector<std::uint64_t>>CargoRailSystem::route(std::uint64_t a,std::uint64_t b)const{std::queue<std::uint64_t>q;std::unordered_map<std::uint64_t,std::uint64_t>p;q.push(a);p[a]=a;while(!q.empty()){auto n=q.front();q.pop();if(n==b)break;std::vector<std::uint64_t>next;for(auto&[_,s]:segments_){if(s.fromNode==n)next.push_back(s.toNode);if(s.bidirectional&&s.toNode==n)next.push_back(s.fromNode);}std::sort(next.begin(),next.end());for(auto x:next)if(!p.contains(x)){p[x]=n;q.push(x);}}if(!p.contains(b))return std::nullopt;std::vector<std::uint64_t>r;for(auto n=b;;n=p[n]){r.push_back(n);if(n==a)break;}std::reverse(r.begin(),r.end());return r;}std::vector<RailMission>CargoRailSystem::plan(std::size_t max){std::sort(shipments_.begin(),shipments_.end(),[](auto&a,auto&b){if(a.priority!=b.priority)return a.priority>b.priority;return a.shipmentId<b.shipmentId;});std::vector<std::uint64_t>cs;for(auto&[id,c]:consists_)if(!c.assigned)cs.push_back(id);std::sort(cs.begin(),cs.end());std::vector<RailMission>o;for(auto cid:cs){if(o.size()>=max||shipments_.empty())break;auto&c=consists_[cid];for(auto it=shipments_.begin();it!=shipments_.end();++it){auto r=route(it->sourceNode,it->targetNode);if(!r)continue;auto q=std::min(c.capacity,it->quantity);o.push_back({it->shipmentId,cid,*r,it->itemId,q});c.assigned=true;if(q==it->quantity)shipments_.erase(it);else it->quantity-=q;break;}}return o;}void CargoRailSystem::complete(std::uint64_t id){auto i=consists_.find(id);if(i!=consists_.end())i->second.assigned=false;}}
